head.script:
scwin.screenId = "jldfil58000n";

///////// 1. 변수 및 선언 영역 /////////



///////// 2. 초기화 영역 /////////

// dataList 단건 표시 복사 — 진입점에서 1회. 데이터 재적재 시 ev:ondataload 가 다시 부른다.
/**
 * @method
 * @name scwin.init_rowCopy
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.init_rowCopy = async function () {
    const rows = [{ childId: "cal_startDate", fn: function () { return String(((cv) => (cv !== undefined && cv !== null && cv !== "") ? cv : "")(dma_pageContext.get("startDate"))); } },
        { childId: "cal_endDate", fn: function () { return String(((cv) => (cv !== undefined && cv !== null && cv !== "") ? cv : "")(dma_pageContext.get("endDate"))); } },
        { childId: "ipt_searchWord", fn: function () { return String(((cv) => (cv !== undefined && cv !== null && cv !== "") ? cv : "")(dma_pageContext.get("searchWord"))); } },
        { childId: "__rb0", fn: function () { return " 전체 " + String(dma_page.get("total")) + "건 (" + String(dma_page.get("currentPage")) + "/" + String(dma_page.get("pageCount")) + " 페이지) "; } }];
    let copied = 0;
    for (let i = 0; i < rows.length; i++) {
        const it = rows[i];
        const c = $c.util.getComponent(it.childId);
        if (!c || typeof c.setValue !== "function") { console.warn("[sdd] 행 복사 대상 부재: " + it.childId); continue; }
        try {
            const v = it.fn();
            if (v !== undefined && v !== null && String(v).trim() !== "") { c.setValue(String(v)); copied++; }
        } catch (e) { await $c.exception.handleError(e, { notify: "none", context: "rowCopy:" + it.childId }); }
    }
    return copied;
};

// [A] 초기 목록 미해결 — jldfil58000n: 열자마자 목록을 채울 근거가 없다(진입 URL 0 · 자기 목록 tx 0 · 화면 자신의 액션 URL 도 못 가름)


// 화면 전환 파라미터 수신 — 엔진 표준(§106). 진입 파라미터 전체를 컨텍스트 dataMap 에 담는다. onpageload 합성 단계.
/**
 * @method
 * @name scwin.init_recvParam
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };

// 화면 진입점 — 초기화 단계를 데이터 의존 순서로 호출한다.
/**
 * @method
 * @name scwin.onpageload
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.onpageload = async function () {
    try {
        scwin.init_recvParam();
        await scwin.init_rowCopy();
    } catch (e) {
        $c.exception.handleError(e, { context: 'jldfil58000n.onpageload' });
    }
};


///////// 3. 컴포넌트 이벤트 영역 /////////

/**
 * @event
 * @name scwin.cal_startDate_onblur
 * @author Inswave
 * @date 2026. 09. 29
 * @param e
 * @returns
 * @hidden N
*/
scwin.cal_startDate_onblur = async function(e){
    try {
        const ev = e;
        const event = ev;
        const selfVar = (ev && (ev.element || ev.target || ev.srcElement)) || this;
        /* sdd-asis-lifecycle:begin cal_startDate_onblur — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
        await (async (c) => { const raw = String((c && c.getValue) ? (c.getValue() ?? "") : ""); if (raw.length === 0) { return true; } const v = raw.split("-").join("").split("/").join(""); if (c && c.setValue) { c.setValue(v); } const lbl = ""; const lp = lbl ? (lbl + ": ") : ""; if (v.length !== 8) { await $c.win.alert(lp + "날짜는 8 자리 YYYYMMDD 형식입니다."); if (c && c.focus) { c.focus(); } return false; } let digits = true; for (let i = 0; i < v.length; i++) { const ch = v.charAt(i); if (ch < "0" || ch > "9") { digits = false; break; } } if (!digits) { await $c.win.alert(lp + "숫자만 입력가능합니다."); if (c && c.focus) { c.focus(); } return false; } const mm = Number(v.substring(4, 6)); if (mm > 12 || mm < 1) { await $c.win.alert(lp + "달은 1 에서 12 사이여야 합니다."); if (c && c.focus) { c.focus(); } return false; } if (!$c.date.checkCalendarFormat(c, "yyyyMMdd", { clearOnInvalid: false })) { await $c.win.alert(lp + " 존재하지 않는 날짜입니다."); if (c && c.focus) { c.focus(); } return false; } return true; })($c.util.getComponent("cal_startDate"));
        /* sdd-asis-lifecycle:end */

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldfil58000n.cal_startDate_onblur' }); }
};

/**
 * @event
 * @name scwin.cal_endDate_onblur
 * @author Inswave
 * @date 2026. 09. 29
 * @param e
 * @returns
 * @hidden N
*/
scwin.cal_endDate_onblur = async function(e){
    try {
        const ev = e;
        const event = ev;
        const selfVar = (ev && (ev.element || ev.target || ev.srcElement)) || this;
        /* sdd-asis-lifecycle:begin cal_endDate_onblur — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
        await (async (c) => { const raw = String((c && c.getValue) ? (c.getValue() ?? "") : ""); if (raw.length === 0) { return true; } const v = raw.split("-").join("").split("/").join(""); if (c && c.setValue) { c.setValue(v); } const lbl = ""; const lp = lbl ? (lbl + ": ") : ""; if (v.length !== 8) { await $c.win.alert(lp + "날짜는 8 자리 YYYYMMDD 형식입니다."); if (c && c.focus) { c.focus(); } return false; } let digits = true; for (let i = 0; i < v.length; i++) { const ch = v.charAt(i); if (ch < "0" || ch > "9") { digits = false; break; } } if (!digits) { await $c.win.alert(lp + "숫자만 입력가능합니다."); if (c && c.focus) { c.focus(); } return false; } const mm = Number(v.substring(4, 6)); if (mm > 12 || mm < 1) { await $c.win.alert(lp + "달은 1 에서 12 사이여야 합니다."); if (c && c.focus) { c.focus(); } return false; } if (!$c.date.checkCalendarFormat(c, "yyyyMMdd", { clearOnInvalid: false })) { await $c.win.alert(lp + " 존재하지 않는 날짜입니다."); if (c && c.focus) { c.focus(); } return false; } return true; })($c.util.getComponent("cal_endDate"));
        /* sdd-asis-lifecycle:end */

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldfil58000n.cal_endDate_onblur' }); }
};

/**
 * @event
 * @name scwin.btn_search_onclick
 * @author Inswave
 * @date 2026. 09. 29
 * @param e
 * @returns
 * @hidden N
*/
scwin.btn_search_onclick = async function(e){
    try {
        const ev = e;
        const event = ev;
        const selfVar = (ev && (ev.element || ev.target || ev.srcElement)) || this;
        /* sdd-asis-lifecycle:begin btn_search_onclick — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
        await scwin.search()
        /* sdd-asis-lifecycle:end */

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldfil58000n.btn_search_onclick' }); }
};

/**
 * @event
 * @name scwin.slc_pageSize_onchange
 * @author Inswave
 * @date 2026. 09. 29
 * @param e
