/**
 * @event
 * @name scwin.grd_bbsList_oncellclick
 * @author Inswave
 * @date 2026. 09. 29
 * @param rowIndex columnIndex columnId
 * @returns
 * @hidden N
*/
scwin.grd_bbsList_oncellclick = async function (rowIndex, columnIndex, columnId) {
    try {
        const dl = $c.util.getComponent('dlt_bbsList');
        if (!dl) { console.error('[sdd] 행 동작 대상 목록 없음: dlt_bbsList'); return; }
        const r = dl.getRowJSON ? dl.getRowJSON(rowIndex) : null;
        if (!r) { return; }
        if (typeof scwin.searchPdsView === 'function') { await scwin.searchPdsView(r["contnId"], r["contnGrpId"], r["ansObjContnId"], r["listInvstgBbsTpCd"], r["contnAttachSeq"]); } else { console.error('[sdd] 행 동작 미정의: scwin.searchPdsView (열 ?)'); await $c.win.alert('이 행 동작을 아직 정하지 못했습니다(전환 미완) — scwin.searchPdsView'); } return;
    } catch (e) {
        await $c.exception.handleError(e, { notify: 'none', context: 'grd_bbsList.oncellclick' });
    }
};


///////// 4. 서브미션 콜백 영역 /////////

/**
 * @method
 * @name scwin.tx_fn_search
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.tx_fn_search = async function () {
    const sbmOptions = {
        id: "tx_fn_search",
        method: "post",
        action: "/listInvstg/bbs.do",
        ref: "dma_searchReq",
        target: "dlt_bbsList=body.content",
        isProcessMsg: false
    };
    let res = null;
    try { res = await $c.sbm.executeDynamic(sbmOptions); }
    catch (_e) { await $c.exception.handleError(_e, { context: "jldfil58000n.tx_fn_search" }); return null; }
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
        return res;
    }

    return res;
};

/**
 * @method
 * @name scwin.tx_fn_SearchPdsView
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.tx_fn_SearchPdsView = async function () {
    const sbmOptions = {
        id: "tx_fn_SearchPdsView",
        method: "post",
        action: "/listInvstg/bbs.do",
        ref: "dma_SearchPdsViewReq",
        target: "dlt_bbsList=body.content",
        isProcessMsg: false
    };
    let res = null;
    try { res = await $c.sbm.executeDynamic(sbmOptions); }
    catch (_e) { await $c.exception.handleError(_e, { context: "jldfil58000n.tx_fn_SearchPdsView" }); return null; }
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
        return res;
    }

    return res;
};

/**
 * @method
 * @name scwin.tx_fn_FileDown
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.tx_fn_FileDown = async function () {
    try { return await $c.data.downFile("/listInvstg/filedown.do", "", ($c.util.getComponent("dma_FileDownReq") ? $c.util.getComponent("dma_FileDownReq").getJSON() : {})); } catch (_e) { await $c.exception.handleError(_e, { context: '다운로드' }); return null; }
};


///////// 5. 일반/업무 함수 영역 /////////

/**
 * @method
 * @name scwin.search
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.search = async function () {
    /* sdd-asis-lifecycle:begin fn_search — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    const frm = (document.PdsListForm || { elements: [] });
    frm.action = 'bbs.do';
    $c.util.getComponent('dma_searchReq').set('method', 'searchPdsList');
    { const nr = await scwin.tx_fn_search(); if (nr && nr.responseJSON && nr.responseJSON.success === true) { $c.win.moveUrl("/jldfil58000/jldfil58000.xml", { "method": 'searchPdsList' }); } };
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.searchPdsView
 * @author Inswave
 * @date 2026. 09. 29
 * @param contnId contnGrpId ansObjContnId listInvstgBbsTpCd contnAttachSeq
 * @returns
 * @hidden N
*/
scwin.searchPdsView = async function (contnId, contnGrpId, ansObjContnId, listInvstgBbsTpCd, contnAttachSeq) {
    /* sdd-asis-lifecycle:begin fn_SearchPdsView — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    const frm = (document.PdsListForm || { elements: [] });
    frm.action = 'bbs.do';
    $c.util.getComponent('dma_searchReq').set('method', 'searchPdsView');
    $c.util.getComponent('dma_searchReq').set('contnId', contnId);
    $c.util.getComponent('dma_searchReq').set('contnGrpId', contnGrpId);
    $c.util.getComponent('dma_searchReq').set('ansObjContnId', ansObjContnId);
    $c.util.getComponent('dma_searchReq').set('listInvstgBbsTpCd', listInvstgBbsTpCd);
    $c.util.getComponent('dma_searchReq').set('contnAttachSeq', contnAttachSeq);
    { const nr = await scwin.tx_fn_SearchPdsView(); if (nr && nr.responseJSON && nr.responseJSON.success === true) { $c.win.moveUrl("/jldfil58001/jldfil58001.xml", { "method": 'searchPdsView', "contnId": contnId, "contnGrpId": contnGrpId, "ansObjContnId": ansObjContnId, "listInvstgBbsTpCd": listInvstgBbsTpCd, "contnAttachSeq": contnAttachSeq }); } };
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.fileDown
 * @author Inswave
 * @date 2026. 09. 29
 * @param contnId contnAttachSeq attachFileNm regDdtm
 * @returns
 * @hidden N
*/
scwin.fileDown = async function (contnId, contnAttachSeq, attachFileNm, regDdtm) {
    /* sdd-asis-lifecycle:begin fn_FileDown — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    const frm = (document.PdsListForm || { elements: [] });
    frm.action = 'filedown.do';
    $c.util.getComponent('dma_searchReq').set('method', 'searchListInvstgBbsFile');
    $c.util.getComponent('dma_searchReq').set('contnId', contnId);
    $c.util.getComponent('dma_searchReq').set('contnAttachSeq', contnAttachSeq);
    $c.util.getComponent('dma_searchReq').set('attachFileNm', attachFileNm);
    $c.util.getComponent('dma_searchReq').set('listInvstgBbsTpCd', '2');
    $c.util.getComponent('dma_searchReq').set('regDdtm', regDdtm);
    await scwin.tx_fn_FileDown();
    /* sdd-asis-lifecycle:end */
};



/**
 * @event
 * @name scwin.krxpage_pagenavigator_116_onclick
 * @author Inswave
 * @date 2026. 09. 29
 * @param index
 * @returns
 * @hidden N
*/
scwin.krxpage_pagenavigator_116_onclick = function (index) { const pi = (index && typeof index === 'object') ? index.newSelectedIndex : index; try { $c.util.getComponent('dma_searchReq').set('pageIndex', pi); } catch (e) { $c.exception.handleError(e, { notify: 'none', context: 'krxpage_pagenavigator_116.page' }); } scwin.search(); };
